mapper.select:
SELECT COALESCE(MAX(FILE_SN), 0)
  FROM ATTACH_FILE_DETAIL
 WHERE ATCH_FILE_ID = #{atchFileId}

SELECT COUNT(*)
  FROM ATTACH_FILE_DETAIL
 WHERE ATCH_FILE_ID = #{atchFileId}

SELECT 
  FROM ATTACH_FILE_DETAIL D
 WHERE D.ATCH_FILE_ID = #{atchFileId}
   AND D.FILE_SN = #{fileSn}

SELECT 
  FROM ATTACH_FILE_DETAIL D
 WHERE D.ATCH_FILE_ID = #{atchFileId}
   AND D.FILE_SN = #{fileSn}
   AND EXISTS (SELECT 1 FROM BOARD B WHERE B.ATCH_FILE_ID = D.ATCH_FILE_ID)

mapper.delete:
DELETE FROM ATTACH_FILE_DETAIL
 WHERE ATCH_FILE_ID = #{atchFileId}
   AND FILE_SN = #{fileSn}
